<?php require __DIR__.'/lib/bootstrap.php';$slug=trim($_GET['slug']??'');$q=db()->prepare('SELECT id,name,niche,slug,city,bio,photo FROM users WHERE slug=?');try{$q->execute([$slug]);$pro=$q->fetch();}catch(Throwable $e){http_response_code(503);exit('Configure o banco de dados para publicar páginas de agendamento.');}if(!$pro){http_response_code(404);exit('Página não encontrada.');}$services=services_for((int)$pro['id']);$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$sid=(int)($_POST['service_id']??0);$date=$_POST['date']??'';$time=$_POST['time']??'';$client=trim($_POST['client_name']??'');$phone=trim($_POST['client_whatsapp']??'');$s=null;foreach($services as $item)if((int)$item['id']===$sid)$s=$item;if(!$s||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||$date<date('Y-m-d')||!preg_match('/^\d{2}:\d{2}$/',$time)||$client===''||$phone==='')$error='Preencha todos os dados e escolha um horário válido.';else{$q=db()->prepare('SELECT COUNT(*) FROM appointments WHERE user_id=? AND appointment_date=? AND start_time=? AND status<>"cancelado"');$q->execute([$pro['id'],$date,$time]);if((int)$q->fetchColumn()>0)$error='Este horário acabou de ser reservado. Escolha outro.';else{$q=db()->prepare('INSERT INTO appointments(user_id,service_id,client_name,client_whatsapp,appointment_date,start_time,status) VALUES(?,?,?,?,?,?,?)');$q->execute([$pro['id'],$sid,$client,$phone,$date,$time,'pendente']);$done=true;}}}$times=['09:00','10:00','11:00','13:00','14:00','15:00','16:00','17:00','18:00'];?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($pro['name']) ?> — Agende pela Fempro</title><link rel="stylesheet" href="assets/css/app.css"></head><body><?php if(!empty($done)): ?><div style="min-height:100vh;display:grid;place-items:center;text-align:center;padding:24px"><div><div style="font-size:52px;color:var(--pink)">✓</div><h1 class="h1">Solicitação enviada!</h1><p class="muted">Seu pedido de horário foi enviado para <?= e($pro['name']) ?>. Aguarde a confirmação.</p><a class="btn" href="index.php">Conhecer a Fempro</a></div></div><?php else: ?><div style="max-width:620px;margin:auto;padding:24px 18px 60px"><div style="text-align:center;padding:22px 10px 30px;background:linear-gradient(130deg,#fff0f6,#fff);border-radius:24px"><img src="../src/assets/fempro-logo.png" style="height:23px" alt="Fempro"><img class="avatar" style="display:block;margin:20px auto 12px;width:92px;height:92px" src="<?= e($pro['photo']?:'../src/assets/pro-portrait.jpg') ?>" alt=""><h1 class="h1"><?= e($pro['name']) ?></h1><p class="muted"><?= e($pro['niche']) ?> · <?= e($pro['city']) ?></p><p class="muted"><?= e($pro['bio']) ?></p></div><h2 style="font:800 22px 'Bricolage Grotesque';margin:28px 0 12px">1. Escolha o serviço</h2><?php if($error): ?><div class="notice"><?= e($error) ?></div><?php endif; ?><form method="post"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><div class="grid"><?php foreach($services as $s): ?><label class="service-choice"><input type="radio" name="service_id" value="<?= (int)$s['id'] ?>" required> <b><?= e($s['name']) ?></b><span style="float:right;font-weight:800"><?= brl((float)$s['price']) ?></span><small class="muted" style="display:block;margin:5px 0 0"><?= (int)$s['duration'] ?> minutos</small></label><?php endforeach; ?></div><h2 style="font:800 22px 'Bricolage Grotesque';margin:28px 0 12px">2. Escolha o dia e horário</h2><div class="field"><label>Data</label><input type="date" name="date" min="<?= date('Y-m-d') ?>" value="<?= date('Y-m-d',strtotime('+1 day')) ?>" required></div><div class="time-grid"><?php foreach($times as $t): ?><label class="time-choice"><input type="radio" name="time" value="<?= $t ?>" required> <?= $t ?></label><?php endforeach; ?></div><h2 style="font:800 22px 'Bricolage Grotesque';margin:28px 0 12px">3. Seus dados</h2><div class="field"><label>Seu nome</label><input name="client_name" required></div><div class="field"><label>WhatsApp</label><input name="client_whatsapp" type="tel" required></div><button class="btn" style="width:100%;margin-top:10px">Solicitar agendamento</button></form><p class="page-footer">Agendamento online por Fempro</p></div><?php endif; ?><script src="assets/js/app-internal.js" defer></script></body></html>
